void Solver::rephase() {
    // Reset rephase counter for new cycle
    rephases = 0;

    // Decrease threshold more aggressively to trigger rephasing sooner
    // This helps adapt to changes in search behavior faster
    threshold *= 0.85;

    // Increase rephase limit moderately to allow more exploration
    // between rephasing events
    rephase_limit += 4096;

    // Update local_best phases based on current trail values
    // This helps maintain good decision heuristics
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            local_best[i] = value[i];
        }
    }
}
